package portfolio.capstone;
import javafx.collections.*; import javafx.concurrent.Task; import javafx.fxml.FXML; import javafx.scene.control.*; import javafx.scene.control.cell.PropertyValueFactory;
public final class StudentController { @FXML private TextField registration,firstName,lastName; @FXML private Button saveButton; @FXML private Label status; @FXML private ProgressIndicator progress; @FXML private TableView<Student> table; @FXML private TableColumn<Student,String> regColumn,firstColumn,lastColumn; private final StudentDao dao=new StudentDao();
 @FXML private void initialize(){ regColumn.setCellValueFactory(c->c.getValue().registrationNumberProperty()); firstColumn.setCellValueFactory(c->c.getValue().firstNameProperty()); lastColumn.setCellValueFactory(c->c.getValue().lastNameProperty()); saveButton.disableProperty().bind(registration.textProperty().isEmpty().or(firstName.textProperty().isEmpty()).or(lastName.textProperty().isEmpty())); load(); }
 private void load(){ Task<ObservableList<Student>> task=new Task<>(){protected ObservableList<Student> call() throws Exception{return FXCollections.observableArrayList(dao.findAll());}}; task.setOnSucceeded(e->{table.setItems(task.getValue());status.setText("Loaded "+task.getValue().size()+" students");}); task.setOnFailed(e->status.setText("Database error: "+task.getException().getMessage())); new Thread(task,"student-loader").start(); }
 @FXML private void save(){ Student s=new Student(0,registration.getText().trim(),firstName.getText().trim(),lastName.getText().trim()); Task<Void> task=new Task<>(){protected Void call() throws Exception{dao.insert(s);return null;}}; progress.visibleProperty().bind(task.runningProperty()); saveButton.disableProperty().bind(task.runningProperty().or(registration.textProperty().isEmpty()).or(firstName.textProperty().isEmpty()).or(lastName.textProperty().isEmpty())); task.setOnSucceeded(e->{status.setText("Saved "+s.getRegistrationNumber());registration.clear();firstName.clear();lastName.clear();load();}); task.setOnFailed(e->status.setText("Save failed: "+task.getException().getMessage())); new Thread(task,"student-saver").start(); }
}
